# Hace desplegable la seccion 'Contratos' en el menu lateral, igual que
# Franquicias/Arrendamientos/Administracion.
# Ejecuta esto parado en la raiz del repo.

$ErrorActionPreference = 'Stop'

# --- frontend/src/components/Layout.jsx ---
$f1b64 = ""
$dir = Split-Path -Parent "frontend\src\components\Layout.jsx"
if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
[System.IO.File]::WriteAllBytes((Resolve-Path ".").Path + "\frontend\src\components\Layout.jsx", [System.Convert]::FromBase64String($f1b64))

Write-Host "Listo: Layout.jsx actualizado."
git add frontend/src/components/Layout.jsx
git commit -m "Hacer desplegable la seccion de Contratos en el menu lateral"
git push origin main